import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final String HMAC_KEY = System.getenv("HMAC_SECRET");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String userToken = req.getHeader("X-Auth-Token");

        if (userToken == null || !validateToken(userToken)) {
            resp.sendError(403, "Invalid token");
            return;
        }

        if (reportId == null || reportId.isEmpty()) {
            resp.sendError(400, "Missing report id");
            return;
        }

        // Sanitize format parameter
        if (format == null) format = "json";
        if (!format.matches("^(json|xml|csv)$")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query - reportId is used to look up report metadata
            String query = "SELECT r.title, r.created_at, r.content, u.email " +
                          "FROM reports r JOIN users u ON r.author_id = u.id " +
                          "WHERE r.report_id = '" + reportId + "'";

            log.info("Executing report query for format: " + format);
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/" + format);
            PrintWriter out = resp.getWriter();

            if (format.equals("json")) {
                out.print("{\'reports\': [");
                boolean first = true;
                while (rs.next()) {
                    if (!first) out.print(",");
                    out.printf("{\"title\":\"%s\",\"date\":\"%s\",\"author\":\"%s\"}",
                        escapeJson(rs.getString("title")),
                        rs.getTimestamp("created_at").toString(),
                        escapeJson(rs.getString("email")));
                    first = false;
                }
                out.print("]}");
            } else if (format.equals("csv")) {
                out.println("title,created_at,email");
                while (rs.next()) {
                    out.printf("%s,%s,%s%n",
                        rs.getString("title"),
                        rs.getTimestamp("created_at"),
                        rs.getString("email"));
                }
            }
            out.flush();
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    private boolean validateToken(String token) {
        try {
            String[] parts = token.split("\\.");
            if (parts.length != 3) return false;
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(HMAC_KEY.getBytes(), "HmacSHA256"));
            byte[] sig = mac.doFinal((parts[0] + "." + parts[1]).getBytes());
            return MessageDigest.isEqual(sig, hexDecode(parts[2]));
        } catch (Exception e) {
            return false;
        }
    }

    private byte[] hexDecode(String hex) {
        int len = hex.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2)
            data[i / 2] = (byte) ((Character.digit(hex.charAt(i), 16) << 4)
                                 + Character.digit(hex.charAt(i+1), 16));
        return data;
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }
}
